import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Mining","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/mining.md","filePath":"es/game-design/professions/mining.md"}'),o={name:"es/game-design/professions/mining.md"};function r(l,e,t,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="mining" tabindex="-1">Mining <a class="header-anchor" href="#mining" aria-label="Enlace permanente a &quot;Mining&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y caminos técnicos siguientes siguen siendo candidatos. <strong>Implementación:</strong> este lote documental no establece ninguna implementación del rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de juego. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/mining.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Mining debería ser geología + extracción + modificación del mundo, además de «clic en montaña -&gt; mineral».</p><h3 id="world-changes" tabindex="-1">Cambios en el mundo <a class="header-anchor" href="#world-changes" aria-label="Enlace permanente a &quot;Cambios en el mundo&quot;">​</a></h3><ul><li>las casillas de roca mineral se agotan físicamente;</li><li>la extracción repetida puede romper una roca/casilla hasta hacerla transitable;</li><li>Mining puede alterar físicamente el tránsito.</li></ul><p>La geología regional debería conservar la identidad de las regiones mineras sin una reaparición ingenua en la casilla exacta. Posible modelo de regeneración/cierre:</p><ul><li>excavación abandonada;</li><li>inestabilidad;</li><li>derrumbe parcial;</li><li>escombros;</li><li>la roca con minerales vuelve/reaparece regionalmente.</li></ul><p>No comprometerse aquí con tiempos ni algoritmos exactos salvo que ya estén documentados en otro lugar.</p><h3 id="prospecting-and-extraction" tabindex="-1">Prospección y extracción <a class="header-anchor" href="#prospecting-and-extraction" aria-label="Enlace permanente a &quot;Prospección y extracción&quot;">​</a></h3><ul><li>prospección;</li><li>reconocimiento de roca/mineral;</li><li>conciencia estructural;</li><li>interpretación de pistas del terreno;</li><li>extracción de mayor rendimiento/calidad mediante mejores decisiones.</li></ul><h3 id="geological-journal" tabindex="-1">Geological Journal <a class="header-anchor" href="#geological-journal" aria-label="Enlace permanente a &quot;Geological Journal&quot;">​</a></h3><ul><li>tipos de roca;</li><li>minerales;</li><li>características de vetas;</li><li>regiones;</li><li>observaciones.</li></ul><h3 id="material-variation" tabindex="-1">Variación de materiales <a class="header-anchor" href="#material-variation" aria-label="Enlace permanente a &quot;Variación de materiales&quot;">​</a></h3><ul><li>composición regional;</li><li>procedencia;</li><li>perfil de impurezas;</li><li>semilla/calidad local.</li></ul><p>Mantener manejable la abstracción.</p><p>El conocimiento de Mining debería informar qué hay y cuánto promete. El de Blacksmithing debería informar para qué sirve ese material.</p><p>Mining puede incluir estabilidad/derrumbes en niveles avanzados, potencialmente conectados con soportes de Carpentry y mecanismos de Tinkering.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Geological Journal.</strong> Registrar tipos de roca, minerales, vetas, regiones y observaciones. La prospección y la pericia estructural ofrecen caminos más allá de extraer materiales brutos.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define la enseñanza y la dirección de límites/aumentos. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, intercambio de conocimiento, maestría manual, producción por lotes, encargos y reputación multidimensional. Aquí no se redefinen esas reglas de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define el rango compartido de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en expediciones <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en expediciones&quot;">​</a></h2><p>Mining identifica qué hay y cuánto promete; Blacksmithing identifica para qué sirve el material. Los soportes de Carpentry y mecanismos de Tinkering son posibles colaboradores avanzados de estabilidad minera.</p><p><a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/es/game-design/living-world.html#terrain-and-authored-geology">Geología diseñada</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar únicamente estados y respuestas que sustenten decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Nada de esto selecciona ID de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Qué rocas diseñadas son modificables; cierre y recuperación regionales; permisos de excavación y seguridad de jugadores atrapados; reglas de derrumbes/soportes; divulgación de rendimiento, procedencia e impurezas. No se selecciona un temporizador exacto, algoritmo de regeneración ni excavación de terreno sin restricciones.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y evidencias existentes de combate no validan este rediseño profesional.</p>',31)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
